original_files.constant/fluidProperties:
FoamFile { version 2.0; format ascii; class dictionary; object fluidProperties; }

schemaVersion 1;
thermoType { type hePsiThermo; mixture pureMixture; transport const; thermo hConst; equationOfState perfectGas; specie specie; energy sensibleInternalEnergy; }
mixture { specie { molWeight 28; } thermodynamics { Cp 1040; Hf 0; } transport { mu 0.001; Pr 0.72; } }
turbulence { simulationType RAS; RAS {model kOmegaSST;turbulence on;printCoeffs on;kOmegaSSTCoeffs {wallTreatment boundaryLayer; boundaryLayer {model reactingSst;nodes 8;maxIterations 60;relativeTolerance 1e-8;absoluteTolerance 1e-10;stretch 2;writeProfiles true;}}} }

original_files.system/fvSchemes:
FoamFile { version 2.0; format ascii; class dictionary; object fvSchemes; }

fluxScheme Kurganov;
gasLimiter barthJespersen;
ddtSchemes { default SSPRK2; }
gradSchemes { default Gauss linear; }
divSchemes
{
 default none;
 div(phi,U) Gauss MUSCL;
 div(phi,e) Gauss MUSCL;
 div(phi,K) Gauss MUSCL;
 div(phi,(p|rho)) Gauss MUSCL;
 div(((rho*nuEff)*dev2(T(grad(U))))) Gauss linear;
}
laplacianSchemes { default Gauss linear corrected; }
interpolationSchemes { default linear; }
snGradSchemes { default corrected; }

wallDist {method meshWave;}
